def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))

    # Fill only enclosed rectangular frame interiors. Each frame's boundary
    # has one color; connected-component bounds isolate multiple same-color
    # frames. A 2x2 cavity maps to 2, other cavities to 7.
    seen_cells = set()
    for sr in range(h):
        for sc in range(w):
            color = grid[sr][sc]
            if color == bg or (sr, sc) in seen_cells:
                continue
            q = deque([(sr, sc)])
            seen_cells.add((sr, sc))
            comp = []
            while q:
                r, c = q.popleft()
                comp.append((r, c))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color
                                and (nr, nc) not in seen_cells):
                            seen_cells.add((nr, nc))
                            q.append((nr, nc))
            r0, r1 = min(r for r, c in comp), max(r for r, c in comp)
            c0, c1 = min(c for r, c in comp), max(c for r, c in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            if (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1+1))
                    and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1+1))):
                fill = 2 if (r1-r0-1)*(c1-c0-1) == 4 else 7
                for r in range(r0+1, r1):
                    for c in range(c0+1, c1):
                        if grid[r][c] == bg:
                            out[r][c] = fill

    # Isolated 3x3 ring motifs are filled at their center with 7.
    for r in range(1, h-1):
        for c in range(1, w-1):
            if grid[r][c] != bg:
                continue
            if all(grid[r+dr][c+dc] != bg for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc) != (0,0)):
                out[r][c] = 7
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
