 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))

    # In these examples, the outlined rectangles are filled with 7, while the
    # smallest 2x2 enclosed cavity uses color 2. Identify cavities as connected
    # components of background cells, then override any corner-leaking frame
    # interiors by direct boundary inspection.
    seen = set()
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != bg or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            cells = []
            edge = False
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                if r in (0, h-1) or c in (0, w-1):
                    edge = True
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            if not edge:
                fill = 2 if len(cells) == 4 else 7
                for r, c in cells:
                    out[r][c] = fill

    # Find each colored frame as a connected component (8-neighbor connectivity
    # joins its corners) and fill its rectangular interior.
    for color in colors - {bg}:
        seen_color = set()
        for sr in range(h):
            for sc in range(w):
                if grid[sr][sc] != color or (sr, sc) in seen_color:
                    continue
                q = deque([(sr, sc)])
                seen_color.add((sr, sc))
                comp = []
                while q:
                    r, c = q.popleft()
                    comp.append((r, c))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen_color:
                                seen_color.add((nr,nc))
                                q.append((nr,nc))
                r0, r1 = min(r for r,c in comp), max(r for r,c in comp)
                c0, c1 = min(c for r,c in comp), max(c for r,c in comp)
                if r1-r0 < 2 or c1-c0 < 2:
                    continue
                if (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and
                    all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1))):
                    fill = 2 if (r1-r0-1)*(c1-c0-1) == 4 else 7
                    for r in range(r0+1,r1):
                        for c in range(c0+1,c1):
                            if grid[r][c] == bg:
                                out[r][c] = fill

    # A 3x3 ring icon is also filled in its center with 7.
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c] == bg and all(grid[r+dr][c+dc] != bg
                    for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc) != (0,0)):
                out[r][c] = 7
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
